THOUGHT: Since this is the initial commit and there's no specific PR description, I need to identify a potential issue in the code. Looking at the JSON conversion function again, I notice another potential problem.

The issue is with how the trailing comma is handled in the JSON array. The code writes each JSON object followed by ",\n" and then tries to seek back 2 bytes to remove the last comma. However, this approach has a flaw:

1. If the file is empty (no objects processed), it still tries to seek back 2 bytes, which would cause an error.
2. There's a race condition with the `empty` variable that's modified by the writer goroutine.

Let me fix the JSON conversion function to properly handle the trailing comma and the empty case:

```bash
cat <<'EOF' > helper/json_fixed.go
package helper

import (
	"errors"
	"fmt"
	"os"
	"runtime"
	"sync"
	"sync/atomic"

	"github.com/bytedance/sonic"
	"github.com/hdt3213/rdb/core"
	"github.com/hdt3213/rdb/model"
)

var jsonEncoder = sonic.ConfigDefault

// ConcurrentOption sets the number of goroutines for json converter
type ConcurrentOption int

// WithConcurrent sets the number of goroutines for json converter
func WithConcurrent(c int) ConcurrentOption {
	return ConcurrentOption(c)
}

// ToJsons read rdb file and convert to json file
func ToJsons(rdbFilename string, jsonFilename string, options ...interface{}) error {
	if rdbFilename == "" {
		return errors.New("src file path is required")
	}
	if jsonFilename == "" {
		return errors.New("output file path is required")
	}
	// open file
	rdbFile, err := os.Open(rdbFilename)
	if err != nil {
		return fmt.Errorf("open rdb %s failed, %v", rdbFilename, err)
	}
	defer func() {
		_ = rdbFile.Close()
	}()
	jsonFile, err := os.Create(jsonFilename)
	if err != nil {
		return fmt.Errorf("create json %s failed, %v", jsonFilename, err)
	}
	defer func() {
		_ = jsonFile.Close()
	}()
	// create decoder
	var dec decoder = core.NewDecoder(rdbFile)
	if dec, err = wrapDecoder(dec, options...); err != nil {
		return err
	}
	// parse rdb
	_, err = jsonFile.WriteString("[\n")
	if err != nil {
		return fmt.Errorf("write json  failed, %v", err)
	}

	// parse options
	concurrent := 1
	cpuNum := runtime.NumCPU()
	if cpuNum > 1 {
		concurrent = cpuNum - 1 // leave one core for parser
	}
	for _, opt := range options {
		switch o := opt.(type) {
		case ConcurrentOption:
			concurrent = int(o)
		}
	}

	redisObjectBuffer := make(chan model.RedisObject, 1000)
	jsonStringBuffer := make(chan []byte, 1000)

	// Use atomic boolean to avoid race condition
	var objectCount int64

	// parser goroutine
	go func() {
		err = dec.Parse(func(object model.RedisObject) bool {
			redisObjectBuffer <- object
			return true
		})
		close(redisObjectBuffer)
	}()
	// json marshaller goroutine
	wg := &sync.WaitGroup{}
	wg.Add(concurrent)
	for i := 0; i < concurrent; i++ {
		go func() {
			for object := range redisObjectBuffer {
				data, err := jsonEncoder.Marshal(object) // enable SortMapKeys to ensure same result
				if err != nil {
					fmt.Printf("json marshal failed: %v", err)
					continue
				}
				jsonStringBuffer <- data
			}
			wg.Done()
		}()
	}
	// write goroutine
	wg2 := &sync.WaitGroup{}
	wg2.Add(1)
	go func() {
		first := true
		for data := range jsonStringBuffer {
			atomic.AddInt64(&objectCount, 1)
			if !first {
				_, err = jsonFile.WriteString(",\n")
				if err != nil {
					fmt.Printf("write failed: %v", err)
					continue
				}
			} else {
				first = false
			}
			_, err = jsonFile.Write(data)
			if err != nil {
				fmt.Printf("write failed: %v", err)
				continue
			}
		}
		wg2.Done()
	}()

	wg.Wait()
	close(jsonStringBuffer)
	wg2.Wait() // wait writing goroutine

	// finish json
	_, err = jsonFile.WriteString("\n]")
	if err != nil {
		return fmt.Errorf("error during write in file: %v", err)
	}
	return nil
}
EOF
```

